window.FIXTURES=window.FIXTURES||{};window.FIXTURES["speech"]={"vid":"6j2RIATwOzc","speaker":"Peter Pellegrini","role":"President","country":"Slovakia","region":"Europe","url":"https://www.youtube.com/watch?v=6j2RIATwOzc","date":"20260923","title":"🇸🇰 Slovakia - President Addresses United Nations General Debate, 81st Session | #UNGA","seconds":669,"words":1248,"counts":{"claims":17,"promises":1,"attacks":0},"topics":[{"topic":"UN reform","share":0.4169,"seconds":279},{"topic":"AI regulation","share":0.2012,"seconds":135},{"topic":"Conflict deescalation","share":0.0974,"seconds":65},{"topic":"Ukraine war","share":0.0973,"seconds":65},{"topic":"International law","share":0.0942,"seconds":63},{"topic":"Israel-Palestine","share":0.093,"seconds":62}],"timeline":[[3,68,null],[70,133,"International law"],[135,199,"UN reform"],[201,278,"UN reform"],[279,351,"AI regulation"],[353,416,"AI regulation"],[418,485,"UN reform"],[486,551,"Conflict deescalation"],[553,619,"Ukraine war"],[621,683,"Israel-Palestine"],[685,756,"UN reform"],[758,768,null]],"stances":{"International law":"Peter Pellegrini argues that the international system is imperfect but should be improved rather than destroyed.","UN reform":"Peter Pellegrini advocates for the United Nations to evolve rather than undergo revolution, specifically calling for Security Council changes to better reflect current realities and represent underrepresented regions.","AI regulation":"Peter Pellegrini argues that AI must benefit all of humanity and requires international frameworks to prevent machines from making life-or-death decisions.","Conflict deescalation":"Peter Pellegrini argues that true leadership requires the courage to de-escalate violence rather than escalate it, emphasizing that ignoring international rules leads to civilian suffering and makes future diplomacy more difficult.","Ukraine war":"Peter Pellegrini states that the war in Ukraine is unacceptable, calls for a ceasefire and diplomatic efforts to end Russia's war, and emphasizes support for international law and human dignity.","Israel-Palestine":"Peter Pellegrini states that both Israelis and Palestinians deserve security and dignity, and that Slovakia supports a negotiated two-state solution."},"claims":[{"t":89,"quote":"Trade is becoming less predictable. Security cooperation is more fragmented.","topic":"International law","kind":"fact"},{"t":95,"quote":"The idea that every country should have a voice is under pressure.","topic":"International law","kind":"fact"},{"t":150,"quote":"Over the past year, Slovakia has hosted several international meetings and offered space for dialogue where we can be useful.","topic":"UN reform","kind":"fact"},{"t":213,"quote":"Slovakia sees its engagement in UN reform as a part of its responsibility to this organization including through UN80 and the implementation of the pact for the future.","topic":"UN reform","kind":"fact"},{"t":229,"quote":"Our responsibility to the wider international order is also reflected in our candidacy for the security council for 2028 and 2029.","topic":"UN reform","kind":"fact"},{"t":345,"quote":"It is already having a negative impact on society, especially in education.","topic":"AI regulation","kind":"fact"},{"t":358,"quote":"Recent assessments show declining test scores across the vast majority of This is a concerning trend that deserves open and serious discussion on international platforms such as the United Nations.","topic":"AI regulation","kind":"fact"},{"t":413,"quote":"Every conflict we prevent saves lives.","topic":"AI regulation","kind":"fact"},{"t":418,"quote":"It protects development. It preserves human dignity.","topic":"UN reform","kind":"fact"},{"t":473,"quote":"Too many conflicts are still driven by the belief that political problems can be solved by force, by changing borders, violating sovereignity, and ignoring international rules.","topic":"UN reform","kind":"fact"},{"t":511,"quote":"When these rules are ignored, civilians suffer. Communities are destroyed, millions are displaced, supply chains are disrupted, prosperity is lost","topic":"Conflict deescalation","kind":"fact"},{"t":553,"quote":"The war in Ukraine, now in its fifth year, continues to bring destruction close to Slovakia's borders.","topic":"Ukraine war","kind":"fact"},{"t":562,"quote":"Attacks on civilian areas and critical infrastructure remain unacceptable.","topic":"Ukraine war","kind":"fact"},{"t":651,"quote":"the civil war in Sudan that has triggered the world's largest humanitarian crisis","topic":"Israel-Palestine","kind":"fact"},{"t":674,"quote":"Armed conflicts have reached levels we have not seen since the Second World War","topic":"Israel-Palestine","kind":"fact"},{"t":698,"quote":"This year, the United Nations will choose its next Secretary General.","topic":"UN reform","kind":"fact"},{"t":721,"quote":"The next Secretary General will inherit an organization under serious security, geopolitical, institutional and financial pressure.","topic":"UN reform","kind":"fact"}],"promises":[{"t":245,"quote":"If elected, Slovakia will focus on four priorities. international law and the UN charter, accountable security institutions, the protection of strategic resources and critical infrastructure, and the security challenges linked to digitalization and artificial","topic":"UN reform","kind":"promise"}],"attacks":[],"greece":[],"said":[],"pickup":[],"transcript":[{"t":3,"topic":null,"text":"The assembly will hear an address by his excellency Peter Pellegrini, the president of the Slovak Republic. I request the protocol to escort his excellency and invite him to address the Mr. Chairman, excellencies, ladies and every country that enters this hall brings its own concerns. For some, security means protecting borders. For others, it means food, water, energy, or the future of their And many countries face all of these challenges at once. That is why a world ruled mainly by power rather than by rules would be dangerous for everyone. For smaller countries such as Slovakia, this is especially clear."},{"t":70,"topic":"International law","text":"But no country, large or small, is truly safe in a world where international law is ignored and institutions are weakened. Sadly, we no longer need to imagine such a world. We can already see parts of it around us. Trade is becoming less predictable. Security cooperation is more fragmented. The idea that every country should have a voice is under pressure. And when rules are weakened, when cooperation is replaced by all of us become more vulnerable. But we still have a choice. The international system we have built is not perfect. It can be slow. It can be frustrating. At times, it does not deliver as quickly as people need. But the solution is not to destroy it. The solution is to make it work better."},{"t":135,"topic":"UN reform","text":"Slovakia is firmly anchored in the United Nations, NATO, and the European Union. We believe in cooperation, but we also believe that institutions must produce real results. Over the past year, Slovakia has hosted several international meetings and offered space for dialogue where we can be useful. We are ready to help bring parties together and to support diplomacy within the UN Because when diplomacy stops, confrontation fills the space. That is why when we speak about the United Nations, I believe in evolution rather than revolution. The world has changed and the United Nations must change with it. The Security Council should better reflect today's realities and give a stronger voice to countries and regions that are still under represented."},{"t":201,"topic":"UN reform","text":"Countries from the region often understand a crisis best. Giving them a stronger voice can help us act earlier and prevent escalation. Slovakia sees its engagement in UN reform as a part of its responsibility to this organization including through UN80 and the implementation of the pact for the future. Our responsibility to the wider international order is also reflected in our candidacy for the security council for 2028 and 2029. We would be of course grateful for your trust and support. If elected, Slovakia will focus on four priorities. international law and the UN charter, accountable security institutions, the protection of strategic resources and critical infrastructure, and the security challenges linked to digitalization and artificial I fully share the concern of the United Nations about the inequalities that can be created by unequal access to artificial intelligence."},{"t":279,"topic":"AI regulation","text":"It is in our common interest that innovation benefits all of humanity, not only the strongest economies or the biggest companies. If AI is available only to a few, new divisions will appear. Entire communities may be left behind. The growing use of AI powered weapons and autonomous systems also requires urgent attention. One principle must remain clear. Machines should never be allowed to make life or death decisions on their own. Just as the international community developed rules for nuclear, chemical, and biological weapons, we also need strong international frameworks for these new technologies. The United Nations can and should play a leading role in this effort. AI is not only a potential threat on the It is already having a negative impact on society, especially in education."},{"t":353,"topic":"AI regulation","text":"An entire generation of young people is being affected. Recent assessments show declining test scores across the vast majority of This is a concerning trend that deserves open and serious discussion on international platforms such as the United Nations. At the same time, we should not see AI only as a risk. It can be also a tool for peace. It can help us analyze information, identify patterns, and overcome language barriers in real time. It can support better decisions, faster responses, and more effective prevention. With responsible use, proper human oversight, and good governance, we can move this technology away from the battlefield and towards diplomacy, mediation, and conflict prevention. and prevention matters. Every conflict we prevent saves lives."},{"t":418,"topic":"UN reform","text":"It protects development. It preserves human dignity. Once violence begins, every solution becomes harder, more costly, and more There is no need to reinvent the wheel when we reform international AI may be revolutionary, but we did not need to reinvent the personal computer in order to build it. The same is true in global politics. We should improve what already exists, not start again from zero. But let's ask ourselves a simple What if we as world leaders would start following the UN charter? Would reform even matter if we finally did our best for global peace? Too many conflicts are still driven by the belief that political problems can be solved by force, by changing borders, violating sovereignity, and ignoring international rules."},{"t":486,"topic":"Conflict deescalation","text":"We need to reject this logic. Leadership is not shown by the willingness to escalate. It requires the courage to deescalate. International rules may sound abstract in this hall, but on the ground they are very real. They can mean the difference between life and death. When these rules are ignored, civilians suffer. Communities are destroyed, millions are displaced, supply chains are disrupted, prosperity is lost, and there is even a deeper danger. If violence becomes normal for the next generation, diplomacy itself will become harder. What is difficult to solve today may become impossible tomorrow. That is why our most urgent task must be clear. Stop the violence, keep diplomacy alive, and prevent today's conflicts from becoming tomorrow's normal."},{"t":553,"topic":"Ukraine war","text":"The war in Ukraine, now in its fifth year, continues to bring destruction close to Slovakia's borders. Attacks on civilian areas and critical infrastructure remain unacceptable. A ceasefire is still distant and lasting peace even further away. We should support every serious diplomatic effort that can help end Russia's war against Ukraine and build a safe future for our neighbor. Our commitment to international law and human dignity cannot stop at Europe's The same basic principles must guide us in the Middle East. International humanitarian law must be Civilians must be protected. Humanitarian aid must reach those who need it, including in Gaza. There can be no justification for terrorism, anti-semitism, anti-Muslim hatred, or calls to violence."},{"t":621,"topic":"Israel-Palestine","text":"Israelis and Palestinians both deserve to live in security and dignity. At Slovakia continues to support a negotiated two-state solution with Israel and independent Palestinian state living side by side in peace and Other conflicts that are currently out of the spotlight must not escape our attention and our efforts to solve them. Take for example the civil war in Sudan that has triggered the world's largest humanitarian crisis. the first words of our charter are, \"We the peoples of the United Nations.\" Today we need that sense of shared responsibility again. Armed conflicts have reached levels we have not seen since the Second World War. civilians continue to pay an unacceptable price."},{"t":685,"topic":"UN reform","text":"We already have institutions. We already have rules. We already have But what we need now is the will to use This year, the United Nations will choose its next Secretary General. Slovakia supports a transparent and inclusive process based on merit with due regard to regional diversity and gender balance. And I would also like to thank Secretary General Antonio Gutes for his dedicated service and leadership during these difficult years. The next Secretary General will inherit an organization under serious security, geopolitical, institutional and financial pressure. But the future of the United Nations will not depend on one person alone. It depends on all of us, on our will, courage and determination. We, the peoples of the United Nations, should not leave the next generation a world where violence is normal and diplomacy is the exception."},{"t":758,"topic":null,"text":"Thank you very much for your attention. On behalf of the assembly, I wish to thank uh the president of the Slovak"}],"compare":[{"topic":"UN & its reform","share":0.4169,"mean":0.2036,"rank":13,"others":170},{"topic":"Artificial Intelligence","share":0.2012,"mean":0.0497,"rank":9,"others":83},{"topic":"International Law & Order","share":0.1916,"mean":0.0597,"rank":16,"others":102},{"topic":"Russia-Ukraine War","share":0.0973,"mean":0.035,"rank":22,"others":44},{"topic":"Israel–Palestine","share":0.093,"mean":0.0522,"rank":40,"others":76}]};
